 function emit(data){if(port)port.postMessage(JSON.stringify(data));window.dispatchEvent(new CustomEvent('vplus:host',{detail:data}));}
 function report(event){if(!video||!Number.isFinite(video.currentTime))return;emit({type:'NATIVE_PROGRESS',event,currentTime:video.currentTime,duration:Number.isFinite(video.duration)?video.duration:0});}
 function time(n){if(!Number.isFinite(n)||n<0)return '—';n=Math.floor(n);return (n>=3600?Math.floor(n/3600)+':':'')+String(Math.floor(n/60)%60).padStart(n>=3600?2:1,'0')+':'+String(n%60).padStart(2,'0');}
 function focus(el){el?.focus({preventScroll:true});el?.scrollIntoView({block:'nearest',inline:'nearest'});}
