 function update(){if(!video)return;const step=config.seekStep||10;for(const action of ['rewind','forward']){const b=$('[data-action="'+action+'"]');b.innerHTML=icons[action];b.querySelector('text').textContent=step;b.setAttribute('aria-label',(action==='rewind'?'Back ':'Forward ')+step+' seconds');b.title=b.getAttribute('aria-label');}const duration=video.duration,position=video.currentTime;$('.time').textContent=time(position)+' / '+time(duration);timeline.disabled=!Number.isFinite(duration)||duration<=0;timeline.value=Number.isFinite(duration)&&duration>0?Math.round(position/duration*1000):0;timeline.style.setProperty('--progress',timeline.value/10+'%');timeline.setAttribute('aria-valuetext',time(position)+' of '+time(duration));$('[data-action=toggle]').innerHTML=icon(video.paused?'play':'pause');$('[data-action=toggle]').setAttribute('aria-label',video.paused?'Play':'Pause');$('[data-action=toggle]').title=video.paused?'Play':'Pause';$('[data-action=volume-toggle]').innerHTML=icon(video.muted||video.volume===0?'muted':'volume');$('[data-action=volume-toggle]').setAttribute('aria-label',video.muted?'Unmute':'Mute');$('.status').textContent=video.readyState<2&&!video.error?'Loading video…':'';if(ui.activeElement!==$('[data-action=volume]'))$('[data-action=volume]').value=video.muted?0:video.volume*100;updateCaptions();if(video.readyState>=2&&!reported){reported=true;emit({type:'NATIVE_READY'});}}
